window.loginAsUser = function(email, name, role, studentId) {
    const user = {
        email: email,
        name: name,
        role: role || 'Student',
        studentId: studentId || ''
    };
    sessionStorage.setItem('loggedInUser', JSON.stringify(user));
    window.location.href = (role === 'Admin') ? 'admin_dashboard.html' : 'student_dashboard.html';
};

window.switchTestAccount = function(email) {
    if (email === 'admin@nu.ac.th') {
        window.loginAsUser('admin@nu.ac.th', 'แอดมินระบบ', 'Admin', '00000000');
        return;
    }
    const stu = window.BEC_TEST_USERS.find(s => s.email === email);
    if (stu) {
        window.loginAsUser(stu.email, stu.name, stu.role, stu.studentId);
    }
};

window.onSelectStudent = function(email) {
    if (!email) return;
    window.switchTestAccount(email);
};

// ─── INITIALIZE ON PAGE LOAD ───
document.addEventListener('DOMContentLoaded', () => {
    // 1. Populate Dropdown on index.html if exists
    const selectEl = document.getElementById('studentSelect');
    if (selectEl) {
        window.BEC_TEST_USERS.forEach(s => {
            const opt = document.createElement('option');
            opt.value = s.email;
            opt.textContent = `${s.studentId} - ${s.name}`;
            selectEl.appendChild(opt);
        });
    }

    // 2. Render Floating QA Switcher on Dashboards if on Test Environment
    if (window.IS_TEST_ENV && (location.pathname.includes('dashboard') || document.getElementById('cardHolderName') || document.getElementById('statTotalEvents'))) {
        renderFloatingQASwitcher();
    }
});

function renderFloatingQASwitcher() {
    if (document.getElementById('qaFloatingWidget')) return;

    // Inject Styles
    const style = document.createElement('style');
    style.textContent = `
        .qa-floating-btn {
            position: fixed;
            bottom: 24px;
            right: 24px;
            z-index: 999999;
            background: #090d16;
            color: #ffffff;
            border: 1px solid rgba(255, 255, 255, 0.25);
            padding: 9px 15px;
            border-radius: 30px;
            font-size: 0.74rem;
            font-weight: 700;
            cursor: pointer;
            box-shadow: 0 10px 25px rgba(0,0,0,0.45);
            display: flex;
            align-items: center;
            gap: 7px;
            font-family: system-ui, -apple-system, sans-serif;
            transition: all 160ms cubic-bezier(0.16, 1, 0.3, 1);
            backdrop-filter: blur(12px);
        }
        .qa-floating-btn:hover {
            transform: translateY(-2px) scale(1.05);
            border-color: #4ade80;
            background: #111827;
        }
        .qa-pulse-dot {
            width: 7px;
            height: 7px;
            border-radius: 50%;
            background: #f59e0b;
            box-shadow: 0 0 8px #f59e0b;
        }
        .qa-modal-overlay {
            position: fixed;
            inset: 0;
            background: rgba(0, 0, 0, 0.65);
            backdrop-filter: blur(8px);
            z-index: 1000000;
            display: flex;
            align-items: center;
            justify-content: center;
            padding: 16px;
            opacity: 0;
            pointer-events: none;
            transition: opacity 180ms ease;
        }
        .qa-modal-overlay.open {
            opacity: 1;
            pointer-events: auto;
        }
        .qa-modal-card {
            background: #ffffff;
            width: 100%;
            max-width: 440px;
            max-height: 80vh;
            border-radius: 20px;
            box-shadow: 0 25px 50px -12px rgba(0,0,0,0.35);
            display: flex;
            flex-direction: column;
            overflow: hidden;
            font-family: system-ui, -apple-system, sans-serif;
            transform: scale(0.95);
            transition: transform 180ms ease;
        }
        .qa-modal-overlay.open .qa-modal-card {
            transform: scale(1);
        }
        .qa-modal-header {
            padding: 16px 20px;
            border-bottom: 1px solid #e2e8f0;
            display: flex;
            align-items: center;
            justify-content: space-between;
            background: #f8fafc;
        }
        .qa-modal-title {
            font-size: 0.88rem;
            font-weight: 800;
            color: #0f172a;
        }
        .qa-modal-close {
            background: none;
            border: none;
            font-size: 1.3rem;
            color: #64748b;
            cursor: pointer;
            padding: 2px 6px;
            line-height: 1;
        }
        .qa-search-box {
            padding: 12px 16px;
            border-bottom: 1px solid #e2e8f0;
        }
        .qa-search-input {
            width: 100%;
            padding: 10px 14px;
            border-radius: 10px;
            border: 1px solid #cbd5e1;
            font-size: 0.82rem;
            outline: none;
            box-sizing: border-box;
            font-family: inherit;
        }
        .qa-search-input:focus {
            border-color: #0284c7;
        }
        .qa-list {
            flex: 1;
            overflow-y: auto;
            padding: 8px 12px;
            max-height: 55vh;
        }
        .qa-user-item {
            padding: 10px 12px;
            border-radius: 10px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            cursor: pointer;
            transition: background 120ms;
            margin-bottom: 4px;
        }
        .qa-user-item:hover {
            background: #f1f5f9;
        }
        .qa-user-item.active {
            background: #eff6ff;
            border: 1px solid #bfdbfe;
        }
        .qa-item-name {
            font-size: 0.82rem;
            font-weight: 700;
            color: #0f172a;
        }
        .qa-item-sub {
            font-size: 0.7rem;
            color: #64748b;
            margin-top: 2px;
        }
        .qa-item-badge {
            font-size: 0.65rem;
            font-weight: 700;
            padding: 3px 8px;
            border-radius: 12px;
            background: #f1f5f9;
            color: #475569;
        }
        .qa-item-badge.admin {
            background: #fef3c7;
            color: #92400e;
        }
    `;
    document.head.appendChild(style);

    // Floating Button
    const btn = document.createElement('button');
    btn.id = 'qaFloatingWidget';
    btn.className = 'qa-floating-btn';
    btn.innerHTML = `<span class="qa-pulse-dot"></span><span>🧪 สลับบัญชีทดสอบ</span>`;
    btn.onclick = openQAModal;
    document.body.appendChild(btn);

    // Modal
    const modal = document.createElement('div');
    modal.id = 'qaModalOverlay';
    modal.className = 'qa-modal-overlay';
    modal.innerHTML = `
        <div class="qa-modal-card" onclick="event.stopPropagation()">
            <div class="qa-modal-header">
                <div>
                    <div class="qa-modal-title">🧪 สลับบัญชีทดสอบ (104 คน)</div>
                    <div style="font-size:0.7rem;color:#64748b;margin-top:2px;">แตะที่ชื่อเพื่อสลับเข้าใช้งานทันทีใน 0 วินาที</div>
                </div>
                <button class="qa-modal-close" onclick="closeQAModal()">&times;</button>
            </div>
            <div class="qa-search-box">
                <input type="text" class="qa-search-input" id="qaSearchInput" placeholder="ค้นหาชื่อ หรือ รหัสนิสิต..." oninput="filterQAUsers(this.value)" />
            </div>
            <div class="qa-list" id="qaUsersList"></div>
        </div>
    `;
    modal.onclick = closeQAModal;
    document.body.appendChild(modal);

    renderQAUsersList('');
}

window.openQAModal = function() {
    const m = document.getElementById('qaModalOverlay');
    if (m) {
        m.classList.add('open');
        const input = document.getElementById('qaSearchInput');
        if (input) { input.value = ''; input.focus(); }
        renderQAUsersList('');
    }
};

window.closeQAModal = function() {
    const m = document.getElementById('qaModalOverlay');
    if (m) m.classList.remove('open');
};

window.filterQAUsers = function(term) {
    renderQAUsersList(term);
};

window.renderQAUsersList = function(searchTerm) {
    const listEl = document.getElementById('qaUsersList');
    if (!listEl) return;
    
    const term = (searchTerm || '').toLowerCase().trim();
    let curr = null;
    try { curr = JSON.parse(sessionStorage.getItem('loggedInUser')); } catch(e) {}
    const currEmail = curr ? curr.email : '';

    let html = '';

    // Admin option always first
    if (!term || 'แอดมิน'.includes(term) || 'admin'.includes(term)) {
        const isCurrAdmin = currEmail === 'admin@nu.ac.th';
        html += `
            <div class="qa-user-item ${isCurrAdmin ? 'active' : ''}" onclick="switchTestAccount('admin@nu.ac.th')">
                <div>
                    <div class="qa-item-name">แอดมินระบบ (Admin)</div>
                    <div class="qa-item-sub">admin@nu.ac.th · จัดการเงินและอนุมัติสลิป</div>
                </div>
                <span class="qa-item-badge admin">แอดมิน</span>
            </div>
        `;
    }

    // Filter students
    const filtered = window.BEC_TEST_USERS.filter(s => {
        if (!term) return true;
        return s.name.toLowerCase().includes(term) || 
               s.studentId.includes(term) || 
               s.email.toLowerCase().includes(term);
    });

    filtered.forEach(s => {
        const isCurr = currEmail === s.email;
        html += `
            <div class="qa-user-item ${isCurr ? 'active' : ''}" onclick="switchTestAccount('${s.email}')">
                <div>
                    <div class="qa-item-name">${s.name}</div>
                    <div class="qa-item-sub">${s.studentId} · ${s.email}</div>
                </div>
                <span class="qa-item-badge">${isCurr ? 'กำลังใช้งาน ✓' : 'นิสิต'}</span>
            </div>
        `;
    });

    if (filtered.length === 0 && (!term || (!'แอดมิน'.includes(term) && !'admin'.includes(term)))) {
        html = '<div style="text-align:center;padding:24px;color:#94a3b8;font-size:0.8rem;">ไม่พบรายชื่อที่ค้นหา</div>';
    }

    listEl.innerHTML = html;
};
